function mostLevels(n: number, edges: number[][]): number {
  const INF = 1e9;
  const d = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0 : INF)));
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { d[u][v] = d[v][u] = 1; adj[u].push(v); adj[v].push(u); }
  const color = new Array(n).fill(-1);
  for (let s = 0; s < n; s++) {
    if (color[s] !== -1) continue;
    color[s] = 0;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop()!;
      for (const v of adj[u]) {
        if (color[v] === -1) { color[v] = 1 - color[u]; stack.push(v); }
        else if (color[v] === color[u]) return -1;
      }
    }
  }
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
  const done = new Array(n).fill(false);
  let total = 0;
  for (let s = 0; s < n; s++) {
    if (done[s]) continue;
    let diameter = 0;
    for (let i = 0; i < n; i++) {
      if (d[s][i] >= INF) continue;
      done[i] = true;
      for (let j = 0; j < n; j++) if (d[i][j] < INF) diameter = Math.max(diameter, d[i][j]);
    }
    total += diameter + 1;
  }
  return total;
}

