function mostLevels(n: number, edges: number[][]): number {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  // label components
  const comp = new Array(n).fill(-1);
  let comps = 0;
  for (let s = 0; s < n; s++) {
    if (comp[s] !== -1) continue;
    comp[s] = comps;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop()!;
      for (const v of adj[u]) if (comp[v] === -1) { comp[v] = comps; stack.push(v); }
    }
    comps++;
  }
  const best = new Array(comps).fill(0);
  const dist = new Array(n);
  const queue = new Array(n);
  for (let s = 0; s < n; s++) {
    dist.fill(-1);
    dist[s] = 0;
    queue[0] = s;
    let head = 0, tail = 1, deepest = 0;
    while (head < tail) {
      const u = queue[head++];
      for (const v of adj[u]) {
        if (dist[v] === -1) {
          dist[v] = dist[u] + 1;
          deepest = dist[v];
          queue[tail++] = v;
        } else if (dist[v] === dist[u]) return -1; // edge inside one layer: odd cycle
      }
    }
    best[comp[s]] = Math.max(best[comp[s]], deepest + 1);
  }
  return best.reduce((a, b) => a + b, 0);
}

